import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.find.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.some.js";
/*eslint-disable*/
import { list_petty_cash_workflows } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import OverlayComp from "@/components/OverlayComp.vue";
import FormConfiguration from "@/components/ExpensesManagement/ExpensePopups/FormConfiguration.vue";
//   import PettyCashRequestFormView from "@/components/Approvals/PettyCashRequestFormView.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  name: "PettyCashRequestApproval",
  mixins: [get_all_org_users],
  components: {
    SnackBar,
    OverlayComp,
    FormConfiguration
    //   PettyCashRequestFormView,
  },
  data() {
    return {
      addData: false,
      stepsSelected: [],
      rolesRM: false,
      loading: false,
      initiaorRM: null,
      initiaorCheck: null,
      initiator: null,
      teamMember: null,
      teamMemberSelected: "",
      SnackBarComponent: {},
      overlay: false,
      selectedData: [],
      flowSteps: [{
        selected: false,
        title: "Initiator"
      }, {
        selected: false,
        title: "Initiator's Reporting Manager"
      }, {
        selected: false,
        title: "Roles"
      }],
      finalArray: [],
      addedRecords: [],
      listSelected: [],
      roleSelected: "",
      itemSelIndex: 0,
      userList: [],
      workflowList: [],
      formObject: {},
      inputRecords: [],
      tableData: {},
      templete: [],
      search: "",
      step: 1,
      addedFlowSteps: [],
      queryCheck: false,
      templateSteps: {},
      radiobutton: null,
      pettyCashRequestHead: null,
      startCheck: false
    };
  },
  async created() {
    this.$store.commit("Setnamesearch", "");
    this.overlay = true;
    await this.get_all_org_users();
    await this.fetch_users();
    await this.get_initiated_petty_cash_request();
  },
  watch: {
    addData: {
      async handler() {
        await this.get_all_org_users();
      }
    },
    teamMemberSelected: {
      handler(newValue) {
        if (newValue && this.radiobutton === "teamMember") {
          this.fetch_selected_data(newValue, "teamMember");
        }
      }
    }
  },
  methods: {
    save_next_step() {
      this.addedFlowSteps = this.addedRecords;
      localStorage.setItem("pettyCashRequestFlowSteps", JSON.stringify(this.addedRecords));
      this.step = 2;
    },
    fetch_users() {
      this.userList = [];
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT") {
          this.userList.push({
            title: element.full_user_name,
            value: element.user_id
          });
        }
      });
      this.userList.sort((a, b) => a.title.localeCompare(b.title));
    },
    save_mutation(value) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: value,
        timeout: 5000,
        Top: true
      };
      this.step = 1;
      this.get_initiated_petty_cash_request();
    },
    fetchclear() {
      this.pettyCashRequestHead = null;
      this.initiator = null;
    },
    add_dialog() {
      this.addData = true;
      this.initiator = null;
      this.radiobutton = null;
      this.pettyCashRequestHead = null;
      this.teamMemberSelected = "";
    },
    close_dialog() {
      this.addData = false;
      if (this.$refs.form) {
        this.$refs.form.reset();
        this.$refs.form.resetValidation && this.$refs.form.resetValidation();
      }
    },
    async add_items() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        let selectedData = {};
        if (this.initiator === "initator") {
          selectedData = {
            step_no: this.addedRecords.length + 1,
            name: "Initiator",
            user_id: "N/A",
            user_type: "initiator",
            workflow_template: this.templete
          };
        } else if (this.radiobutton === "teamMember" && this.teamMemberSelected) {
          selectedData = {
            step_no: this.addedRecords.length + 1,
            name: this.teamMemberSelected.title,
            user_id: this.teamMemberSelected.value,
            user_type: "team_member",
            workflow_template: this.templete
          };
        } else if (this.pettyCashRequestHead === "pettyCashRequestHeadNew") {
          selectedData = {
            step_no: this.addedRecords.length + 1,
            name: "Group Head",
            user_id: "N/A",
            user_type: "expense_group",
            workflow_template: this.templete
          };
        }
        if (Object.keys(selectedData).length > 0 && !this.isNameAlreadyExists(selectedData.name)) {
          this.addedRecords.push(selectedData);
          this.close_dialog();
        } else if (this.isNameAlreadyExists(selectedData.name)) {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: "Data Already Exists",
            timeout: 5000,
            Top: true
          };
        }
      }
    },
    isNameAlreadyExists(exitsName) {
      // console.log(this.addedRecords.some((obj) => obj.name === exitsName));
      return this.addedRecords.some(obj => obj.name === exitsName);
    },
    add_row(index) {
      this.itemSelIndex = index;
      this.add_dialog();
    },
    delete_record(index) {
      this.addedRecords.splice(index, 1);
    },
    previous_step() {
      this.step = 1;
    },
    error_msg(value) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: value,
        timeout: 5000,
        Top: true
      };
    },
    fetch_selected_data(type, action) {
      // console.log(type, action);
      // Handle different selection types for petty cash request
      if (action === "initator") {
        this.initiator = type;
        this.pettyCashRequestHead = null;
        this.radiobutton = null;
        this.teamMemberSelected = "";
      } else if (action === "teamMember") {
        this.teamMember = type;
        this.initiator = null;
        this.pettyCashRequestHead = null;
      } else if (action === "pettycashrequest") {
        this.pettyCashRequestHead = type;
        this.initiator = null;
        this.radiobutton = null;
        this.teamMemberSelected = "";
      }
    },
    async get_initiated_petty_cash_request() {
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_petty_cash_workflows, {
          input: {
            organization_id: data.organization.organization_id
          }
        }));
        var response = JSON.parse(result.data.list_petty_cash_workflows);
        this.overlay = false;
        this.tableData = {};
        if (response.Status == "SUCCESS") {
          // Find the workflow with form_unique_type "PETTY_CASH_ADVANCE"
          const pettyCashAdvanceWorkflow = response.data.find(workflow => workflow.form_unique_type === "PETTY_CASH_ADVANCE");
          if (pettyCashAdvanceWorkflow) {
            this.templete = pettyCashAdvanceWorkflow.workflow_template;
            this.templateSteps = pettyCashAdvanceWorkflow;
            this.tableData = pettyCashAdvanceWorkflow;
            this.addedRecords = this.tableData.workflow_approval_steps;
            this.queryCheck = true;
          } else {
            this.tableData = {};
            this.overlay = false;
            this.SnackBarComponent = {
              SnackbarVmodel: true,
              SnackbarColor: "orange",
              SnackbarText: "No PETTY_CASH_ADVANCE workflow found",
              timeout: 5000,
              Top: true
            };
          }
        } else {
          this.tableData = {};
          this.overlay = false;
        }
      } catch (error) {
        this.overlay = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
